#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int s;
        cin >> s;
        char g;
        if (s >= 90) g = 'A';
        else if (s >= 80) g = 'B';
        else if (s >= 60) g = 'C';
        else g = 'F';
        cout << s << ' ' << g << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<string> grid = {"..#", "#.."};
int h = 2, w = 3;

bool freeCell(int r, int c) {
    // 범위를 먼저 확인해야 범위 밖 접근이 없어요(&& 는 앞이 false 면 뒤를 안 봐요)
    return 0 <= r && r < h && 0 <= c && c < w && grid[r][c] == '.';
}

int main() {
    int qs[5][2] = {{0, 0}, {0, 2}, {2, 0}, {-1, 1}, {1, 2}};
    for (auto &q : qs) cout << q[0] << ' ' << q[1] << ' ' << boolalpha << freeCell(q[0], q[1]) << '\n';
    int x = 7;
    cout << (x % 2 ? "홀수" : "짝수") << '\n';
    int y = 50;
    cout << (0 <= y <= 10) << ' ' << (0 <= y && y <= 10) << '\n';
    return 0;
}

